import { Injectable, inject } from '@angular/core';
import { SupabaseClient } from '@supabase/supabase-js';
import { Database } from 'supabase/types/supabase';

export type ApiKey = Database['public']['Tables']['api_keys']['Row'];

@Injectable({
  providedIn: 'root',
})
export class ApiKeyService {
  private supabaseClient = inject<SupabaseClient<Database>>(SupabaseClient);


  async getApiKeys(includeRevoked: boolean = false): Promise<ApiKey[]> {
    const { data, error } = await this.supabaseClient
      .from('api_keys')
      .select('*')
      .order('created_at', { ascending: false });

    if (error) {
      throw error;
    }

    return includeRevoked ? data : data.filter((key) => !key.revoked);
  }

  async createApiKey(name: string, daysValid: number = 365): Promise<ApiKey> {
    const { data, error } = await this.supabaseClient.rpc('create_api_key', {
      key_name: name,
      days_valid: daysValid,
    });

    if (error) {
      throw error;
    }

    return data;
  }

  async revokeApiKey(keyId: string): Promise<void> {
    const { error } = await this.supabaseClient.rpc('revoke_api_key', {
      key_id: keyId,
    });

    if (error) {
      throw error;
    }
  }
}
