import { CommonModule } from '@angular/common';
import { Component, inject, input, numberAttribute, OnInit } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import {
  IonBackButton,
  IonBadge,
  IonButton,
  IonButtons,
  IonCard,
  IonCardContent,
  IonCardHeader,
  IonCardTitle,
  IonContent,
  IonHeader,
  IonIcon,
  IonItem,
  IonLabel,
  IonList,
  IonSelect,
  IonSelectOption,
  IonSpinner,
  IonTitle,
  IonToolbar,
  ViewWillEnter,
} from '@ionic/angular/standalone';
import { addIcons } from 'ionicons';
import {
  addCircleOutline,
  documentTextOutline,
  imageOutline,
  keyOutline,
  searchOutline,
  trashOutline,
  sparklesOutline,
} from 'ionicons/icons';
import {
  catchError,
  combineLatest,
  from,
  map,
  of,
  ReplaySubject,
  shareReplay,
  startWith,
  switchMap,
} from 'rxjs';
import { getRoutePath } from '../app.routes';
import { AlertService } from '../common/alert/alert.service';
import { ApiKey, ApiKeyService } from '../common/api-key/api-key.service';
import { AuthService } from '../common/auth/auth.service';
import { ClipboardService } from '../common/capacitor/clipboard.service';
import { CreditsService, CreditPackage } from '../common/credits/credits.service';
import { LocalStorageService } from '../common/storage/local-storage.service';
import { SubscriptionService } from '../common/subscription/subscription.service';
import { UserService } from '../common/user/user.service';

@Component({
  selector: 'app-account',
  templateUrl: './account.page.html',
  styleUrls: ['./account.page.scss'],
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    IonHeader,
    IonToolbar,
    IonTitle,
    IonContent,
    IonButtons,
    IonBackButton,
    IonCard,
    IonCardHeader,
    IonCardTitle,
    IonCardContent,
    IonList,
    IonItem,
    IonLabel,
    IonIcon,
    IonButton,
    IonSpinner,
    IonBadge,
    IonSelect,
    IonSelectOption,
  ],
})
export class AccountPage implements OnInit, ViewWillEnter {
  private alertService = inject(AlertService);
  private apiKeyService = inject(ApiKeyService);
  private authService = inject(AuthService);
  private clipboardService = inject(ClipboardService);
  private creditsService = inject(CreditsService);
  private localStorageService = inject(LocalStorageService);
  private router = inject(Router);
  private subscriptionService = inject(SubscriptionService);
  private userService = inject(UserService);

  // Query params for purchase return (web flow)
  purchase = input<string>();
  credits = input(0, { transform: numberAttribute });

  readonly searchRoutePath = getRoutePath('search');
  readonly infinity = Number.POSITIVE_INFINITY;
  creditPackages: CreditPackage[] = [];
  private refresh$ = new ReplaySubject<void>(1);

  readonly modelProviders: Array<{value: 'openai' | 'veniceai' | 'xai', label: string}> = [
    { value: 'openai', label: 'OpenAI' },
    { value: 'veniceai', label: 'Venice AI' },
    { value: 'xai', label: 'xAI' },
  ];

  selectedModelProvider: 'openai' | 'veniceai' | 'xai' =
    this.localStorageService.getItem('preferred-model-provider') || 'openai';

  viewModel$ = this.refresh$.pipe(
    switchMap(async () => {
      const user = await this.userService.getUser();
      if (!user) {
        throw new Error('User not found');
      }
      return user;
    }),
    switchMap((user) =>
      combineLatest([
        from(this.subscriptionService.getCurrentSubscription()),
        from(this.subscriptionService.getUsageCounts(user.id)),
        from(this.apiKeyService.getApiKeys()),
        from(this.creditsService.getBalance()),
        from(this.creditsService.getPackages()),
        of(false), // End loading state
      ])
    ),
    map(([subscription, usage, apiKeys, creditBalance, creditPackages, isLoading]) => {
      this.creditPackages = creditPackages;
      return {
        subscription,
        usage,
        apiKeys,
        creditBalance,
        isLoading,
      };
    }),
    startWith({ ...defaultSubscription, apiKeys: [], creditBalance: 0, isLoading: true }),
    catchError((error) => {
      this.alertService.createNotice({
        message: 'Failed to load account data',
        duration: 5000,
        positionAnchor: 'footer',
      });
      return of({ ...defaultSubscription, apiKeys: [], creditBalance: 0, isLoading: false });
    }),
    shareReplay(1)
  );

  constructor() {
    addIcons({
      addCircleOutline,
      documentTextOutline,
      imageOutline,
      keyOutline,
      searchOutline,
      sparklesOutline,
      trashOutline,
    });
  }

  async ngOnInit() {
    // Handle purchase return (web flow)
    const purchaseStatus = this.purchase();
    if (purchaseStatus === 'success') {
      this.alertService.createNotice({
        message: 'Payment received! Your credits will appear shortly.',
        duration: 4000,
        color: 'success',
        positionAnchor: 'footer',
      });

      // Clear query params from URL
      this.router.navigate([], { queryParams: {}, replaceUrl: true });
    } else if (purchaseStatus === 'cancelled') {
      this.alertService.createNotice({
        message: 'Purchase cancelled.',
        duration: 3000,
        positionAnchor: 'footer',
      });

      // Clear query params from URL
      await this.router.navigate([], { queryParams: {}, replaceUrl: true });
    }
  }

  ionViewWillEnter() {
    this.refresh$.next();
    this.selectedModelProvider =
      this.localStorageService.getItem('preferred-model-provider') || 'openai';
  }

  onModelProviderChange(provider: 'openai' | 'veniceai' | 'xai') {
    this.localStorageService.setItem('preferred-model-provider', provider);
    this.alertService.createNotice({
      message: 'Preferred model provider updated',
      duration: 2000,
      positionAnchor: 'footer',
    });
  }

  async openCreateApiKeyModal() {
    const alert = await this.alertService.presentAlert({
      header: 'Create API Key',
      inputs: [
        {
          name: 'name',
          type: 'text',
          placeholder: 'Enter a name for your API key',
        },
      ],
      buttons: [
        {
          text: 'Cancel',
          role: 'cancel',
        },
        {
          text: 'Create',
          role: 'confirm',
        },
      ],
    });

    const result = await alert.onDidDismiss();

    if (result.role === 'confirm' && result.data?.values?.name?.trim()) {
      await this.createApiKey(result.data.values.name);
    }
  }

  private async createApiKey(name: string) {
    try {
      const apiKey = await this.apiKeyService.createApiKey(name);
      this.refresh$.next();

      await this.alertService.createNotice({
        message:
          "API key created successfully. Make sure to copy your key now as it won't be shown again.",
        duration: 10000,
        positionAnchor: 'footer',
      });

      await this.alertService.presentAlert({
        header: 'Your New API Key',
        message: apiKey.token,
        buttons: [
          {
            text: 'Copy',
            handler: async () => {
              await this.clipboardService.writeToClipboard(apiKey.token);
              await this.alertService.createNotice({
                message: 'API key copied to clipboard',
                duration: 2000,
                positionAnchor: 'footer',
              });
              return false; // prevents alert from closing
            },
          },
          'OK',
        ],
      });
    } catch (error) {
      await this.alertService.createNotice({
        message: 'Failed to create API key',
        duration: 5000,
        positionAnchor: 'footer',
      });
    }
  }

  async revokeApiKey(key: ApiKey) {
    const confirmed = await this.alertService.createConfirm({
      header: 'Revoke API Key',
      message: `Are you sure you want to revoke the API key "${key.name}"? This action cannot be undone.`,
      confirmButtonText: 'Revoke',
    });

    const result = await confirmed.onDidDismiss();

    if (result.role !== 'confirm') {
      return;
    }

    try {
      await this.apiKeyService.revokeApiKey(key.id);
      this.refresh$.next();

      await this.alertService.createNotice({
        message: 'API key revoked successfully',
        duration: 5000,
        positionAnchor: 'footer',
      });
    } catch (error) {
      await this.alertService.createNotice({
        message: 'Failed to revoke API key',
        duration: 5000,
        positionAnchor: 'footer',
      });
    }
  }

  async removeAccount() {
    const confirmed = await this.alertService.createConfirm({
      header: 'Remove Account',
      message:
        'Your account and all associated data will be permanently deleted.',
      confirmButtonText: 'Remove',
    });

    const result = await confirmed.onDidDismiss();

    if (result.role !== 'confirm') {
      return;
    }

    await this.authService.deleteAccount();
  }

  async purchaseCredits(pkg: CreditPackage) {
    try {
      const url = await this.creditsService.purchasePackage(pkg.id);
      if (url) {
        // Web flow: redirect to Stripe Checkout
        window.location.href = url;
      }
      // Native flow: Browser was opened, deep link will return user to app
    } catch (error) {
      console.error('Purchase error:', error);
      this.alertService.createNotice({
        message: 'Failed to start checkout. Please try again.',
        duration: 5000,
        color: 'danger',
        positionAnchor: 'footer',
      });
    }
  }
}

const defaultSubscription = {
  subscription: {
    plan: {
      name: 'Loading...',
      image_generation_limit: 0,
    },
  },
  usage: {
    images: 0,
  },
};
