import { Injectable, inject } from '@angular/core';
import { SupabaseClient } from '@supabase/supabase-js';
import { Database } from 'supabase/types/supabase';

export interface SubscriptionPlan {
  id: string;
  name: string;
  description: string | null;
  verse_limit: number;
  note_limit: number;
  image_generation_limit: number;
}

export interface UserSubscription {
  id: string;
  user_id: string;
  plan_id: string;
  created_at: string;
  plan: SubscriptionPlan;
}

@Injectable({
  providedIn: 'root',
})
export class SubscriptionService {
  private supabaseClient = inject<SupabaseClient<Database>>(SupabaseClient);


  async getCurrentSubscription(): Promise<UserSubscription> {
    const { data: subscription, error } = await this.supabaseClient
      .from('user_subscriptions')
      .select('*, plan:subscription_plans(*)')
      .single();

    if (error) {
      throw new Error(`Failed to get subscription: ${error.message}`);
    }

    return subscription as UserSubscription;
  }

  async getUsageCounts(userId: string | undefined): Promise<{
    verses: number;
    notes: number;
    images: number;
  }> {
    if (!userId) {
      throw new Error('User ID is required');
    }

    const currentMonth = new Date();
    const startOfMonth = new Date(
      currentMonth.getFullYear(),
      currentMonth.getMonth(),
      1
    ).toISOString();

    // Get verse count
    const { count: verseCount } = await this.supabaseClient
      .from('verses')
      .select('*', { count: 'exact', head: true })
      .eq('user_id', userId)
      .gte('created_at', startOfMonth);

    // Get note count
    const { count: noteCount } = await this.supabaseClient
      .from('notes')
      .select('*', { count: 'exact', head: true })
      .eq('user_id', userId)
      .gte('created_at', startOfMonth);

    // Get image generation count
    const { count: imageCount } = await this.supabaseClient
      .from('activity_log')
      .select('*', { count: 'exact', head: true })
      .eq('user_id', userId)
      .eq('activity_type', 'image_generation')
      .gte('created_at', startOfMonth);

    return {
      verses: verseCount || 0,
      notes: noteCount || 0,
      images: imageCount || 0,
    };
  }
} 